<style>
@font-face{font-family:Club;src:url('assets/tomorrows-bouquet-lato.ttf')}*{box-sizing:border-box}body{margin:0;background:#f4e9cb;color:#283e36;font-family:Club,'Trebuchet MS',sans-serif}main{max-width:1160px;margin:auto;padding:26px}a{color:inherit}nav{display:flex;justify-content:space-between;font-size:13px;letter-spacing:.08em}header{padding:35px 0 25px;display:flex;gap:30px;align-items:end;justify-content:space-between}h1{font-family:Georgia,serif;font-size:clamp(40px,6vw,76px);letter-spacing:-.055em;line-height:.95;margin:10px 0;max-width:650px}h1 em{color:#b94628;font-weight:normal}header p{max-width:300px;line-height:1.65;margin:0}.label{font-size:12px;font-weight:bold;text-transform:uppercase;letter-spacing:.16em}.layout{display:grid;grid-template-columns:1fr 1fr;border:2px solid #283e36;border-radius:24px;overflow:hidden;background:#fff7e2;box-shadow:8px 8px 0 #cdbf9b}.scene{position:relative;min-height:510px;background:#e6ddb5;overflow:hidden}.scene img{width:100%;height:100%;object-fit:cover;position:absolute;inset:0}.balloons{position:absolute;top:17%;left:20%;width:60%;display:flex;justify-content:center;gap:3px;z-index:1}.balloon{height:68px;width:40px;border-radius:50%;background:#ce5736;border:2px solid #293e36;position:relative;transition:transform .5s,opacity .5s}.balloon:nth-child(2n){background:#839966;margin-top:20px}.balloon:after{content:'';position:absolute;top:100%;left:50%;height:150px;width:1px;background:#293e36;transform:rotate(-8deg)}.balloon.lost{transform:translateY(-160px);opacity:0}.speech{position:absolute;bottom:22px;left:20px;right:20px;background:#fff7e2;border:2px solid #283e36;border-radius:16px;padding:16px;font-family:Georgia,serif;font-size:21px;box-shadow:3px 3px 0 #283e36}.game{padding:30px;display:flex;flex-direction:column;justify-content:center}.topline{display:flex;justify-content:space-between;gap:10px;font-size:13px}.clue{font-family:Georgia,serif;font-size:27px;line-height:1.3;margin:22px 0 18px;min-height:100px}.word{display:flex;flex-wrap:wrap;gap:5px;margin:0 0 20px;min-height:45px}.letter{font-size:24px;min-width:25px;text-align:center;border-bottom:2px solid #283e36;padding-bottom:6px}.space{width:14px}.keys{display:grid;grid-template-columns:repeat(7,1fr);gap:7px}button{font:inherit;font-weight:bold;color:#283e36;cursor:pointer;border:1.5px solid #283e36;border-radius:8px;background:#f4e9cb;min-height:44px;box-shadow:0 3px 0 #283e36}button:hover:not(:disabled){background:#e4c46e;transform:translateY(-1px)}button:focus-visible,a:focus-visible,textarea:focus-visible{outline:3px solid #b94628;outline-offset:3px}button:disabled{cursor:default;box-shadow:none;opacity:.42}button.hit{background:#a8c78c;opacity:1}button.miss{background:#e7c7b4;opacity:.65}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}.actions button{padding:0 15px}.actions .primary{background:#283e36;color:#fff7e2}.result{margin:18px 0 0;line-height:1.6;min-height:48px}.lower{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin-top:36px}h2{font-family:Georgia,serif;font-size:27px;margin:0 0 12px}details{border-top:2px solid #283e36;padding-top:18px}summary{font-weight:bold;cursor:pointer}textarea{display:block;resize:vertical;width:100%;padding:12px;font:16px Club,sans-serif;min-height:150px;border:2px solid #283e36;background:#fff7e2;border-radius:9px}.muted{font-size:14px;line-height:1.6}.stamps{display:flex;gap:6px;flex-wrap:wrap}.stamp{border:1px dashed #283e36;padding:6px 10px;border-radius:50%;font-size:13px}footer{margin-top:30px;padding:20px 0;border-top:1px solid #a4a385;font-size:13px;line-height:1.7}#customStatus{min-height:22px}@media(max-width:720px){main{padding:18px}header{display:block;padding:26px 0}header p{max-width:none;margin-top:20px}.layout,.lower{grid-template-columns:1fr}.scene{min-height:320px}.game{padding:23px}.clue{min-height:auto;font-size:24px}.balloons{top:9%}.balloon{height:54px;width:34px}.balloon:after{height:115px}.speech{font-size:18px;bottom:12px}.lower{gap:24px}.keys{gap:6px}h1{max-width:400px}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}
