<nav><a href="index.php">← Chloe Reads Jon</a><span>EST. 2006 / REIMAGINED 2026</span></nav>
<header><div><div class="label">A little lift for your vocabulary</div><h1>Kangaroo’s<br><em>Kindness Club.</em></h1></div><p>What’s underneath “I’m upset”? Sometimes, a need with a name. Guess the letters. Keep Roo afloat. No insults, just questionable aeronautics.</p></header>
<div class="layout"><section class="scene" aria-label="Roo’s balloon flight"><img src="assets/kindness-kangaroo.webp" alt="Original storybook illustration of a scarf-wearing kangaroo in a basket over eucalyptus hills"><div class="balloons" id="balloons" aria-hidden="true"></div><div class="speech" id="speech">“I have needs. Mostly altitude.”</div></section>
<section class="game" aria-label="Word guessing game"><div class="topline"><span class="label" id="pack">Human needs</span><span id="lives"></span></div><p class="clue" id="clue"></p><div class="word" id="word" role="img" aria-label="Hidden word"></div><div class="keys" id="keys" aria-label="Choose a letter"></div><div class="actions"><button id="hint">One free letter</button><button class="primary" id="next">Next word →</button></div><p class="result" id="result" aria-live="polite"></p></section></div>
<div class="lower"><section><h2>A word is a little doorway.</h2><p class="muted">Seven wrong guesses bring Roo gently back to earth. Correct letters cost nothing. Use the keyboard or tap. Each new word restores the balloons. The clue names one possible need, not the only explanation for a feeling.</p><div class="label" style="margin-bottom:12px">Words you’ve carried aloft</div><div id="stamps" class="stamps"><span class="muted">Your first discovery goes here.</span></div></section>
<details><summary>Make your own vocabulary flight</summary><p class="muted">One word or phrase per line, optionally followed by | and a clue. English letters, spaces and hyphens, up to 24 characters. Try science words, Zelda items, or your spelling list. Nothing is uploaded or saved.</p><label for="custom" class="label">Your words</label><textarea id="custom" placeholder="photosynthesis | Plants turning sunlight into food&#10;master sword | A legendary blade"></textarea><div class="actions"><button id="load">Fly with my words</button><button id="reset">Human-needs pack</button></div><p id="customStatus" class="muted" aria-live="polite"></p></details></div>
<footer>Inspired by Jon’s <a href="?source=1">Customizable word game for building a domain-specific vocabulary</a>, where he used Hangaroo to learn the language of human needs. This is an original, gentler game, not a recreation of Hangaroo. Original artwork generated for this page.</footer>
</main><script>
'use strict';
const needs=[
['respect','Being taken seriously, even when someone disagrees.','Could you hear my idea before deciding?'],
['warmth','A welcome that feels friendly rather than frosty.','Could we share a hug or a kind hello?'],
['purpose','A sense that what you do matters.','Could I help with something meaningful?'],
['belonging','Knowing there is a place for you in the group.','Could I join you?'],
['autonomy','Having room to make your own choices.','Could I choose how to do this?'],
['rest','A pause that lets your body and mind recover.','Could we take a quiet break?'],
['play','Room for delight, silliness, and exploration.','Could we do something just for fun?'],
['clarity','Understanding what is happening or expected.','Could you explain what you mean?'],
['connection','Feeling in touch with someone, not just near them.','Could we spend a little time together?'],
['safety','Being free from threats and able to relax.','Could we find somewhere calmer?'],
['fairness','Having everyone’s needs considered, not only one person’s.','Could we find a way that works for both of us?'],
['trust','Confidence that words and actions will line up.','Could we agree on what happens next?'],
['beauty','Something lovely that refreshes your attention.','Could we stop and look at that sunset?'],
['learning','The chance to discover and understand something new.','Could you show me how that works?'],
['support','Not having to carry something difficult alone.','Could you help me with this part?'],
['understanding','Feeling that someone really gets what you mean.','Could you tell me what you heard me say?']
];
const $=id=>document.getElementById(id);let deck=needs,queue=[],item,guessed=new Set(),wrong=0,ended=false,hinted=false,found=new Set();
function rand(n){const a=new Uint32Array(1);let x;const bound=4294967296-4294967296%n;do{crypto.getRandomValues(a);x=a[0]}while(x>=bound);return x%n}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=rand(i+1);[a[i],a[j]]=[a[j],a[i]]}return a}
function start(){if(!queue.length)queue=shuffle([...deck]);item=queue.pop();guessed=new Set();wrong=0;ended=false;hinted=false;$('clue').textContent=item[1];$('result').textContent='Guess a letter. Seven balloons, one mystery.';$('speech').textContent='“I have needs. Mostly altitude.”';$('hint').disabled=false;render()}
function render(){
$('lives').textContent=(7-wrong)+' / 7 balloons';
$('word').replaceChildren();let spoken=[];
for(const c of item[0].toUpperCase()){const el=document.createElement('span');el.className=c===' '?'space':'letter';const visible=!/[A-Z]/.test(c)||guessed.has(c)||ended;el.textContent=visible?c:'·';spoken.push(visible?c:'blank');$('word').append(el)}$('word').setAttribute('aria-label',spoken.join(' '));
$('keys').replaceChildren();for(const c of 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'){const b=document.createElement('button');b.textContent=c;b.disabled=ended||guessed.has(c);if(guessed.has(c))b.className=item[0].toUpperCase().includes(c)?'hit':'miss';b.setAttribute('aria-label',c+(b.className==='hit'?', correct':b.className==='miss'?', not in word':''));b.onclick=()=>guess(c);$('keys').append(b)}
$('balloons').replaceChildren();for(let i=0;i<7;i++){const b=document.createElement('div');b.className='balloon'+(i<wrong?' lost':'');$('balloons').append(b)}
}
function guess(c){if(ended||guessed.has(c))return;guessed.add(c);const hit=item[0].toUpperCase().includes(c);if(!hit)wrong++;
const won=[...item[0].toUpperCase()].every(x=>!/[A-Z]/.test(x)||guessed.has(x));
if(won||wrong>=7){ended=true;$('hint').disabled=true;$('result').textContent=(won?'Aloft! ':'A gentle landing. The word was ')+(!won?item[0]+'. ':'')+(item[2]?'Try asking: “'+item[2]+'”':'Your vocabulary just got a little bigger.');$('speech').textContent=won?'“Excellent. Emotional literacy AND aviation.”':'“Still a kangaroo. Still very much fine.”';if(won){found.add(item[0]);$('stamps').replaceChildren();for(const w of found){const s=document.createElement('span');s.className='stamp';s.textContent=w;$('stamps').append(s)}}}
else{$('result').textContent=hit?'That letter is aboard!':'Not this time. '+(7-wrong)+' balloons remain.';$('speech').textContent=hit?'“A letter! Just what the basket ordered.”':['“A bold choice. The alphabet has other plans.”','“That balloon wanted a solo career.”','“We are descending with dignity.”'][rand(3)]}
render()}
$('hint').onclick=()=>{if(ended||hinted)return;hinted=true;$('hint').disabled=true;const missing=[...new Set([...item[0].toUpperCase()].filter(c=>/[A-Z]/.test(c)&&!guessed.has(c)))];if(missing.length)guess(missing[rand(missing.length)])};
$('next').onclick=start;
$('load').onclick=()=>{const lines=$('custom').value.split('\n').filter(s=>s.trim());const words=[];let rejected=0;for(const line of lines.slice(0,100)){const [w,...rest]=line.split('|');const word=w.trim().toLowerCase();if(!/^[a-z][a-z -]{0,23}$/.test(word)){rejected++;continue}if(!words.some(x=>x[0]===word))words.push([word,rest.join('|').trim().slice(0,200)||'A mystery from your custom word pack.',''])}if(!words.length){$('customStatus').textContent='Add at least one valid word first. Your current flight is unchanged.';return}deck=words;queue=[];$('pack').textContent='Your word pack';$('customStatus').textContent=words.length+' words loaded.'+(rejected?' '+rejected+' invalid lines skipped.':'')+(lines.length>100?' Only the first 100 lines were read.':'');start()};
$('reset').onclick=()=>{deck=needs;queue=[];$('pack').textContent='Human needs';$('customStatus').textContent='Human-needs pack restored.';start()};
document.addEventListener('keydown',e=>{if(['TEXTAREA','INPUT','BUTTON','SUMMARY','A'].includes(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;if(/^[a-z]$/i.test(e.key)){e.preventDefault();guess(e.key.toUpperCase())}});
start();
</script></body></html>